      if (!result.executed) return;
      const { report } = result;
      console.info("integrity_scheduler_result", report.status, report.version, report.findings.length, report.evidenceFingerprint, result.checkpoints?.household.refreshed ?? 0, result.checkpoints?.household.rejected ?? 0, result.checkpoints?.platform.eventCount ?? 0);
    } catch {
      console.error("integrity_scheduler_result", "incomplete");
    } finally {
      state.running = false;
    }
  };

  await tick();
  state.timer = setInterval(() => {
    void tick();
  }, integrityConfig.intervalHours * 60 * 60 * 1000);
  state.timer.unref?.();
  return state;
}

export async function startPlatformHealthScheduler() {
  const state = getState();
  if (state.started) return state;
  state.started = true;

  const tick = async () => {
    if (state.running) return;
    state.running = true;
    try {
      await runPlatformHealthCheck();
    } catch {
      console.error("platform_health_tick_failed", "platform_health_failed");
    } finally {
      state.running = false;
    }
  };

  await tick();
  state.timer = setInterval(() => {
    void tick();
  }, POLL_MS);
  state.timer.unref?.();
  return state;
}

